function roomArt(room, completedCount = 0) {
  const wall = room === 'kitchen' ? '#E4EDDE' : room === 'family' ? '#ECE4D3' : '#F1E6CA';
  const common = `<ellipse cx="497" cy="545" rx="391" ry="55" fill="#294836" opacity=".08"/><path d="M48 370 538 267 949 385 457 568 48 416z" fill="#B6CBB2"/><path d="m48 370 490-110 411 125-492 153z" fill="#D8E6CD" stroke="#BDCCAE" stroke-width="2"/><path d="M48 370V76L538 22v238z" fill="${wall}"/><path d="M538 22 949 119v266L538 260z" fill="#E6DCC0"/><path d="m49 366 488-107 410 122" stroke="#B9B797" stroke-width="8"/><path d="m139 412 493-123m-359 166 491-125m-342 172 484-126" stroke="#C3D6B8" stroke-width="2"/><path d="M106 108 266 90v151l-160 34z" fill="#B9D1CC" stroke="#FFF8DF" stroke-width="13"/><path d="m111 169 148-22m-75-49v154" stroke="#FFF8DF" stroke-width="7"/><path d="m113 227 34-36 35 11 26-44 49 30v47l-143 32z" fill="#91B8A7" opacity=".65"/><path d="m106 284 163-36" stroke="#A78E64" stroke-width="12" stroke-linecap="round"/><path d="M111 304v40m7-38 4 36" stroke="#967D58" stroke-width="5"/><path d="m93 329 41-9-2 36-32 8z" fill="#CBA178"/><path d="M114 330c-16-15-20-40-5-46 4 14 9 26 5 46m3-2c3-31 27-41 29-25-7 13-17 20-29 25" fill="#7EA579"/><path d="M903 364v-58" stroke="#709068" stroke-width="6"/><path d="M902 338c-30-3-40-26-25-29 14 4 24 13 25 29m0-8c25-4 32-23 20-30-12 6-21 16-20 30" fill="#90B080"/><path d="m881 347 44 3-8 40-31-4z" fill="#C4A07B"/>`;
  let furniture;
  if (room === 'kitchen') {
    furniture = `<path d="m188 292 294-57 238 78-299 76z" fill="#D4BC91"/><path d="m188 292 233 75v118l-233-88z" fill="#EBDFBB" stroke="#BBA885" stroke-width="3"/><path d="m421 367 299-76v126l-299 84z" fill="#C2D1AF" stroke="#9BB28E" stroke-width="3"/><path d="M227 324v81m66-60v83m66-64v88m152-103v102m90-126v102" stroke="#C1BE9B" stroke-width="3"/><path d="m484 369 17-5m73-18 16-5m71-18 17-5" stroke="#79906F" stroke-width="5" stroke-linecap="round"/><path d="m241 278 93-18 81 24-101 26z" fill="#789F9D" stroke="#638B88" stroke-width="3"/><path d="m254 279 77-12 59 17-76 18z" fill="#B6CED0"/><path d="M307 270v-42c0-23 35-30 42-5v13" stroke="#91AFA8" stroke-width="10" stroke-linecap="round"/><path d="m585 170 99 26v58l-100-28z" fill="#FFF6D9" stroke="#C4BDA0" stroke-width="4"/><path d="m604 193 58 16m-58-1 45 12" stroke="#C4CDAC" stroke-width="5" stroke-linecap="round"/>`;
  } else if (room === 'family') {
    furniture = `<path d="m210 373 324-76 187 80-326 103z" fill="#D5BD93" opacity=".55"/><path d="m157 245 136-28 82 32v124l-136 47-82-38z" fill="#D2A67C"/><path d="m161 247 76 29 131-32v113l-131 46-76-32z" fill="#E8BB91" stroke="#BC8F68" stroke-width="3"/><path d="m165 328 74 30 131-43v43l-131 46-74-31z" fill="#F0CEA9" stroke="#BC8F68" stroke-width="3"/><path d="M235 282v66m-45-80v60m115-67v62" stroke="#D3A57C" stroke-width="3"/><path d="m410 219 161-21 107 27-166 32z" fill="#B39369"/><path d="m410 220 102 36v82l-102-37zm102 36 166-31v83l-166 35z" fill="#D9C29B" stroke="#A78B63" stroke-width="3"/><path d="m462 211 0-95 145-13v93z" fill="#587574" stroke="#405F5C" stroke-width="6"/><path d="m471 121 127-10v77l-127 14z" fill="#C0D9CF"/><path d="m514 150 11-10 10 10-10 19z" fill="#92B39D"/><path d="m530 200 0 13 22 4" stroke="#405F5C" stroke-width="7" stroke-linecap="round"/>`;
  } else {
    furniture = `<path d="m243 297 292-55 205 78-297 79z" fill="#D0AB77" stroke="#A78256" stroke-width="3"/><path d="m243 297 200 82 297-74v18l-297 84-200-86z" fill="#B78D5D"/><path d="M269 323v142m169-72v123m273-184v128" stroke="#99764F" stroke-width="15" stroke-linecap="round"/><path d="m406 303 140-29 79 27-145 36z" fill="#82999A" stroke="#506D6B" stroke-width="3"/><path d="m419 299 0-83 137-18v78z" fill="#709495" stroke="#476968" stroke-width="5"/><path d="m429 223 117-16v61l-117 24z" fill="#BCDBCE"/><path d="m472 238 17-8 17 5-7 21-16 8-13-7z" fill="#78A18B"/><path d="m428 308 58 17 99-24" stroke="#B9C9C0" stroke-width="4"/><path d="m555 313 22 8 14-5-22-7z" fill="#ADBCB2"/>`;
  }
  const lights = Array.from({ length: 3 }, (_, index) => `<path d="m${630 + index * 41} ${78 + index * 9} 0 15m-7-8h14" stroke="${index < completedCount ? '#D3A43B' : '#D6D0B4'}" stroke-width="4" stroke-linecap="round"/>`).join('');
  return svg(`${common}${furniture}${lights}`, '0 0 1000 620', 'pr-care-scenery');
}

const layouts = {
  desk: { pieces: [[36, 49], [54, 38], [55, 80]], targets: [[14, 70], [84, 29], [85, 76]], label: 'Study room', clean: 'Room to breathe' },
  kitchen: { pieces: [[39, 53], [55, 79], [54, 27]], targets: [[85, 54], [14, 77], [85, 20]], label: 'Kitchen', clean: 'A thoughtful care plan' },
  family: { pieces: [[39, 63], [55, 37], [56, 81]], targets: [[14, 75], [85, 76], [85, 24]], label: 'Family room', clean: 'More life for useful things' },
};

/** Original illustrated room thumbnail for the shared game chooser. */
export function careArt() {
  return `<span class="pr-care-hub-art" aria-hidden="true">${roomArt('desk', 2)}</span>`;
}

export function renderCare({ level, completed = {}, selected = null } = {}) {
  if (!level) return '<div class="pr-care"><p>Choose a room to get started.</p></div>';
  const room = layouts[level.room || level.id] ? level.room || level.id : 'desk';
  const layout = layouts[room];
  const pieces = Array.isArray(level.pieces) ? level.pieces : [];
  const targets = Array.isArray(level.targets) ? level.targets : [];
  const isDone = id => completed instanceof Set ? completed.has(id) : Array.isArray(completed) ? completed.includes(id) : Boolean(completed?.[id]);
  const doneCount = pieces.filter(piece => isDone(piece.id)).length;
  const targetMarkup = targets.map((target, index) => {
    const placed = pieces.filter(piece => isDone(piece.id) && piece.answer === target.id);
    const position = layout.targets[index] || [84, 30 + index * 22];
    return `<button type="button" class="pr-care-target${placed.length ? ' is-complete' : ''}" data-target="${escape(target.id)}" data-care-target="${index}" style="--cx:${position[0]}%;--cy:${position[1]}%" aria-label="${escape(target.label)}${placed.length ? ', placed: ' + escape(placed.map(piece => piece.label).join(', ')) : ''}"><span class="pr-care-destination">${targetArt(target.kind)}${placed.map(piece => `<span class="pr-care-placed-object">${pieceArt(piece.kind)}</span>`).join('')}<span class="pr-care-drop-ring" aria-hidden="true"></span></span><span class="pr-care-target-label">${escape(target.label)}</span>${placed.length ? '<span class="pr-care-done-mark" aria-hidden="true">✓</span>' : '<span class="pr-care-place-cue" aria-hidden="true">↓</span>'}</button>`;
  }).join('');
  const pieceMarkup = pieces.map((piece, index) => {
    const position = layout.pieces[index] || [40 + index * 10, 50];
    if (isDone(piece.id)) return `<span class="pr-care-clear-space" data-care-piece="${index}" style="--cx:${position[0]}%;--cy:${position[1]}%" aria-hidden="true"><i>✦</i><span>Space made!</span></span>`;
    return `<button type="button" class="pr-care-piece${selected === piece.id ? ' is-selected' : ''}" data-piece="${escape(piece.id)}" data-care-piece="${index}" style="--cx:${position[0]}%;--cy:${position[1]}%" aria-pressed="${selected === piece.id}" aria-label="${escape(piece.label)}"><span class="pr-care-piece-lift">${pieceArt(piece.kind)}</span><span class="pr-care-piece-label">${escape(piece.label)}</span><span class="pr-care-pick-cue" aria-hidden="true">${selected === piece.id ? 'Choose its place' : 'Move me'}</span></button>`;
  }).join('');
  return `<section class="pr-care pr-care-${room}${doneCount === pieces.length && pieces.length ? ' is-room-ready' : ''}" aria-label="${escape(layout.label)} care puzzle"><div class="pr-care-scene" data-care-room="${room}">${roomArt(room, doneCount)}<div class="pr-care-room-tab" aria-hidden="true"><span class="pr-care-room-dot"></span>${escape(layout.label)}</div>${targetMarkup}${pieceMarkup}<div class="pr-care-room-progress" aria-hidden="true"><span>${doneCount === pieces.length && pieces.length ? escape(layout.clean) : 'Small changes. Longer life.'}</span><b>${doneCount}<i>/</i>${pieces.length}</b></div><span class="pr-care-room-spark pr-care-spark-one" aria-hidden="true">✦</span><span class="pr-care-room-spark pr-care-spark-two" aria-hidden="true">✦</span></div></section>`;
}
